val selector = SelectorManager(Dispatchers.IO)
val server = aSocket(selector).tcp().bind(port = 8080)
while (true) {
    val socket = server.accept()          // suspends; resumes when the selector reports readiness
    launch {                              // the handler, one coroutine per connection
        socket.openReadChannel().copyTo(socket.openWriteChannel())
    }
}
